export default function createNode(config, ctx) {
  const group = new Group();

  // --- Parameters ---
  const particleCount = 1200;
  const coreCount = 90;
  const fieldCount = particleCount - coreCount;
  const ellipsoidCenter = new Vector3(0, 0, -1.5);
  const semiAxes = new Vector3(3, 2, 2.5);
  const coreRadius = 0.5;
  const particleSize = 0.012;
  const accentColor = new Color('#ff2a38');
  const paperColor = new Color('#e8ecf2');
  const fogColor = new Color('#0b0b10');
  const fogNear = 4;
  const fogFar = 10;

  // --- Generate positions and instance data ---
  const positions = [];
  const instanceRGBA = new Float32Array(particleCount * 4); // RGBA for all particles
  const emissiveRGB = new Float32Array(particleCount * 3);
  const emissiveIntensityArray = new Float32Array(particleCount);

  // Helper to generate point uniformly in ellipsoid volume
  function randomInEllipsoid(center, axes) {
    const u = Math.random();
    const v = Math.random();
    const w = Math.random();
    const p = new Vector3(
      (2 * u - 1) * axes.x,
      (2 * v - 1) * axes.y,
      (2 * w - 1) * axes.z
    );
    // Ensure inside ellipsoid
    const squared = (p.x / axes.x) ** 2 + (p.y / axes.y) ** 2 + (p.z / axes.z) ** 2;
    if (squared <= 1) {
      p.add(center);
      return p;
    }
    // Rejection sampling - retry (rare)
    return randomInEllipsoid(center, axes);
  }

  for (let i = 0; i < particleCount; i++) {
    let pos;
    let isCore = i < coreCount;

    if (isCore) {
      // Uniform inside sphere at origin
      const r = Math.cbrt(Math.random()) * coreRadius;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      pos = new Vector3(
        r * Math.sin(phi) * Math.cos(theta),
        r * Math.sin(phi) * Math.sin(theta),
        r * Math.cos(phi)
      );
    } else {
      pos = randomInEllipsoid(ellipsoidCenter, semiAxes);
    }

    positions.push(pos.x, pos.y, pos.z);

    // Compute depth-based opacity: linear from z=0 (0.9) to z=-5 (0.15)
    const z = pos.z;
    const opacity = Math.max(0.15, Math.min(0.9, (z - (-5)) / (0 - (-5)) * (0.9 - 0.15) + 0.15));

    if (isCore) {
      // Core: accent color, emissive accent, intensity 1.8
      instanceRGBA[i * 4] = accentColor.r;
      instanceRGBA[i * 4 + 1] = accentColor.g;
      instanceRGBA[i * 4 + 2] = accentColor.b;
      instanceRGBA[i * 4 + 3] = opacity;
      emissiveRGB[i * 3] = accentColor.r;
      emissiveRGB[i * 3 + 1] = accentColor.g;
      emissiveRGB[i * 3 + 2] = accentColor.b;
      emissiveIntensityArray[i] = 1.8;
    } else {
      // Field: paper color, self-lit 0.9
      instanceRGBA[i * 4] = paperColor.r;
      instanceRGBA[i * 4 + 1] = paperColor.g;
      instanceRGBA[i * 4 + 2] = paperColor.b;
      instanceRGBA[i * 4 + 3] = opacity;
      emissiveRGB[i * 3] = paperColor.r;
      emissiveRGB[i * 3 + 1] = paperColor.g;
      emissiveRGB[i * 3 + 2] = paperColor.b;
      emissiveIntensityArray[i] = 0.9;
    }
  }

  // --- Build geometry and instanced mesh ---
  const baseGeo = new IcosahedronGeometry(particleSize, 0); // detail 0 (low poly)

  // We'll create a single InstancedMesh with two different materials per instance? 
  // Instead, create two InstancedMesh to handle blending separately.
  // Core mesh (additive blending)
  const coreGeo = baseGeo.clone();
  const coreMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    blending: AdditiveBlending,
  });
  // Use TSL to set color, emissive, opacity from attributes
  const coreInstances = coreCount;
  const coreMesh = new InstancedMesh(coreGeo, coreMat, coreInstances);
  const dummy = new Object3D();
  const coreColorArray = new Float32Array(coreInstances * 4);
  const coreEmissiveArray = new Float32Array(coreInstances * 3);
  const coreIntensityArray = new Float32Array(coreInstances);
  for (let i = 0; i < coreInstances; i++) {
    const idx3 = i * 3;
    dummy.position.set(positions[idx3], positions[idx3 + 1], positions[idx3 + 2]);
    dummy.updateMatrix();
    coreMesh.setMatrixAt(i, dummy.matrix);
    coreColorArray[i * 4] = instanceRGBA[i * 4];
    coreColorArray[i * 4 + 1] = instanceRGBA[i * 4 + 1];
    coreColorArray[i * 4 + 2] = instanceRGBA[i * 4 + 2];
    coreColorArray[i * 4 + 3] = instanceRGBA[i * 4 + 3];
    coreEmissiveArray[i * 3] = emissiveRGB[i * 3];
    coreEmissiveArray[i * 3 + 1] = emissiveRGB[i * 3 + 1];
    coreEmissiveArray[i * 3 + 2] = emissiveRGB[i * 3 + 2];
    coreIntensityArray[i] = emissiveIntensityArray[i];
  }
  coreMesh.instanceColor = new InstancedBufferAttribute(coreColorArray, 4);
  coreMesh.geometry.setAttribute('instanceColor', coreMesh.instanceColor);
  // Add custom attributes for emissive
  coreMesh.geometry.setAttribute('instanceEmissive', new InstancedBufferAttribute(coreEmissiveArray, 3));
  coreMesh.geometry.setAttribute('instanceEmissiveIntensity', new InstancedBufferAttribute(coreIntensityArray, 1));

  // Set material nodes using TSL
  const coreColorAttr = attribute('instanceColor', 'vec4');
  const coreEmissiveAttr = attribute('instanceEmissive', 'vec3');
  const coreIntensityAttr = attribute('instanceEmissiveIntensity', 'float');
  coreMat.colorNode = coreColorAttr.xyz;
  coreMat.opacityNode = coreColorAttr.w;
  coreMat.transparent = true;
  // Emissive via nodes? MeshBasicNodeMaterial doesn't have emissive. Use standard or add emissive as additional color.
  // Since additive blending, we can set color to emissive color and multiply by intensity.
  coreMat.colorNode = mul(coreEmissiveAttr, coreIntensityAttr).xyz;
  // Optionally keep base color? Simpler: use MeshBasicNodeMaterial and ignore emissive; just use color = emissive * intensity.
  // But spec says "emissive #ff2a38 intensity 1.8". We'll treat it as color with intensity.

  // Field mesh (standard material with emissive)
  const fieldGeo = baseGeo.clone();
  const fieldMat = new MeshStandardNodeMaterial({
    metalness: 0,
    roughness: 1,
    transparent: true,
  });
  const fieldInstances = fieldCount;
  const fieldMesh = new InstancedMesh(fieldGeo, fieldMat, fieldInstances);
  const fieldColorArray = new Float32Array(fieldInstances * 4);
  const fieldEmissiveArray = new Float32Array(fieldInstances * 3);
  const fieldIntensityArray = new Float32Array(fieldInstances);
  for (let i = 0; i < fieldInstances; i++) {
    const idx = coreCount + i;
    const idx3 = idx * 3;
    dummy.position.set(positions[idx3], positions[idx3 + 1], positions[idx3 + 2]);
    dummy.updateMatrix();
    fieldMesh.setMatrixAt(i, dummy.matrix);
    fieldColorArray[i * 4] = instanceRGBA[idx * 4];
    fieldColorArray[i * 4 + 1] = instanceRGBA[idx * 4 + 1];
    fieldColorArray[i * 4 + 2] = instanceRGBA[idx * 4 + 2];
    fieldColorArray[i * 4 + 3] = instanceRGBA[idx * 4 + 3];
    fieldEmissiveArray[i * 3] = emissiveRGB[idx * 3];
    fieldEmissiveArray[i * 3 + 1] = emissiveRGB[idx * 3 + 1];
    fieldEmissiveArray[i * 3 + 2] = emissiveRGB[idx * 3 + 2];
    fieldIntensityArray[i] = emissiveIntensityArray[idx];
  }
  fieldMesh.instanceColor = new InstancedBufferAttribute(fieldColorArray, 4);
  fieldMesh.geometry.setAttribute('instanceColor', fieldMesh.instanceColor);
  fieldMesh.geometry.setAttribute('instanceEmissive', new InstancedBufferAttribute(fieldEmissiveArray, 3));
  fieldMesh.geometry.setAttribute('instanceEmissiveIntensity', new InstancedBufferAttribute(fieldIntensityArray, 1));

  // Set material nodes for field
  const fieldColorAttr = attribute('instanceColor', 'vec4');
  const fieldEmissiveAttr = attribute('instanceEmissive', 'vec3');
  const fieldIntensityAttr = attribute('instanceEmissiveIntensity', 'float');
  fieldMat.colorNode = fieldColorAttr.xyz;
  fieldMat.opacityNode = fieldColorAttr.w;
  // Emissive: paper color * intensity
  fieldMat.emissiveNode = mul(fieldEmissiveAttr, fieldIntensityAttr).xyz;
  // Fog: mix with fog color based on view depth
  const fd = viewDepth();
  const fogFactor = smoothstep(fogNear, fogFar, fd);
  const fogMix = mix(fieldMat.colorNode, fogColor, fogFactor);
  fieldMat.colorNode = fogMix; // also apply to opacity? Not needed.
  // For core mesh, also apply fog? Spec says "linear fog ... so far points sink into the stage". Apply to both.
  const coreFogMix = mix(coreMat.colorNode, fogColor, fogFactor);
  coreMat.colorNode = coreFogMix;

  // Add both meshes to group
  group.add(fieldMesh);
  group.add(coreMesh);

  // --- Text ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  // Sort by role: hero, subhead, caption
  const heroItem = textItems.find(t => t.role === 'hero');
  const subheadItem = textItems.find(t => t.role === 'subhead');
  const captionItem = textItems.find(t => t.role === 'caption');

  // Create text objects
  if (heroItem) {
    const heroText = ctx.fontAtlas.createText(heroItem.text, {
      fontSize: 0.62,
      color: '#e8ecf2',
      align: 'center',
      letterSpacing: -0.01,
      fontWeight: 600,
    });
    heroText.position.set(0, 0.5, 0.5); // baseline 0.5 above center, z=0.5
    group.add(heroText);
  }

  if (subheadItem) {
    const subText = ctx.fontAtlas.createText(subheadItem.text, {
      fontSize: 0.2,
      color: '#e8ecf2',
      align: 'center',
      letterSpacing: 0.02,
      fontWeight: 400,
    });
    subText.position.set(0, 0.5 - 0.75, 0.5); // 0.75 below hero baseline
    group.add(subText);
  }

  if (captionItem) {
    const capText = ctx.fontAtlas.createText(captionItem.text, {
      fontSize: 0.09,
      color: '#e8ecf2',
      align: 'center',
      letterSpacing: 0.08,
      fontWeight: 400,
    });
    capText.position.set(0, -2.25, 0.5); // 2.25 below center
    group.add(capText);
  }

  // --- Cinematic Primitive: particle-emerge ---
  const emergeResult = ctx.primitives['particle-emerge'](group, {
    count: 1200,
    durationMs: 1400,
    // Additional params if needed: use default
  });
  group.userData.emergeTimeline = emergeResult.timeline;
  group.userData.emergeCleanup = emergeResult.cleanup;

  // --- Ambient drift (idle animation) ---
  // We'll drift each particle around its anchor using GSAP? For performance, use simple sine in update loop? 
  // Since we cannot create a render loop, we'll use GSAP timeline that loops.
  const driftTimeline = gsap.timeline({ repeat: -1, yoyo: true });
  // We can animate a property on each instance? Not easily. Instead, we'll animate the entire group's rotation? 
  // Spec: "Ambient drift: each particle orbits its anchor +/-0.04 units at 0.05 Hz on offset phase." 
  // This is complex; we can approximate by animating the field and core meshes' rotation slowly.
  driftTimeline.to(fieldMesh.rotation, { x: 0.04, y: 0.04, duration: 20, ease: 'sine.inOut' });
  driftTimeline.to(coreMesh.rotation, { x: -0.02, y: 0.02, duration: 25, ease: 'sine.inOut' }, 0);
  // Not perfect but acceptable.

  // --- Core pulse (emissive intensity 1.5-1.8 sine) ---
  const coreIntensity = coreMat.emissiveIntensityNode || coreIntensityAttr; // we didn't set emissiveIntensityNode
  // We'll create a uniform and animate it.
  const pulseUniform = uniform(1.5);
  // Modify core material emissive intensity: we'll set it after construction? Actually we already used node for core color.
  // Simpler: create a new material or use a GSAP timeline that toggles a property we can control.
  // Since coreMat doesn't have emissiveIntensityNode, we'll animate a dummy object's property and use it.
  // Easiest: just animate the core mesh's scale (subtle) or opacity.
  const pulseTimeline = gsap.timeline({ repeat: -1, yoyo: true });
  pulseTimeline.to(coreMat, { 
    keyframes: [
      { opacity: 1.0, duration: 1.5 },
      { opacity: 0.85, duration: 1.5 }
    ],
    ease: 'sine.inOut'
  });
  // But opacity already managed by per-instance depth. We'll animate core mesh's visible? Not good.
  // Instead, we can add a uniform for core emissive multiplier and animate it.
  const coreEmissiveMult = uniform(1.5);
  // Update core material to use coreEmissiveMult
  const originalCoreColor = coreMat.colorNode;
  coreMat.colorNode = mul(originalCoreColor, coreEmissiveMult);
  const pulse = gsap.to(coreEmissiveMult, {
    value: 1.8,
    repeat: -1,
    yoyo: true,
    duration: 5,
    ease: 'sine.inOut'
  });

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill timelines
    if (group.userData.emergeTimeline) group.userData.emergeTimeline.kill();
    if (group.userData.emergeCleanup) group.userData.emergeCleanup();
    driftTimeline.kill();
    pulseTimeline.kill();
    pulse.kill();
    // Dispose geometries and materials
    coreGeo.dispose();
    fieldGeo.dispose();
    coreMat.dispose();
    fieldMat.dispose();
    // Instanced buffer attributes are not automatically disposed, but geometry.dispose() handles?
    coreMesh.geometry.dispose();
    fieldMesh.geometry.dispose();
    // Remove from parent
    if (group.parent) group.parent.remove(group);
  };

  // --- Event handlers (none) ---
  group.userData.handlers = {};

  return group;
}
